                if (elem[i].name.indexOf('audtOpinTpCd1') >= 0) continue; //감사의견(개별기준)
                if (elem[i].name.indexOf('totAsstAmt1') >= 0) continue; //자산총계
                if (elem[i].name.indexOf('totDebtAmt1') >= 0) continue; //부채총계
                if (elem[i].name.indexOf('totCap1') >= 0) continue; //자본총계
                if (elem[i].name.indexOf('cap1') >= 0) continue; //자본금
