                if (elem[i].name.indexOf('netincmAmt1') >= 0) continue; //당기순이익				
                if (elem[i].name.indexOf('bzActivCashFlowAmt1') >= 0) continue; //영업활동으로인한현금흐름				
                if (elem[i].name.indexOf('connAudtOpinTpCd1') >= 0) continue; //감사의견(연결기준)
                //E:발행회사에 관한 사항(재무현황) 필수값 빼기

                //S:발행회사에 관한 사항((영업용)순자본비율등) 필수값 빼기	
                if (elem[i].name == 'ncrAcntclsYymm1') {
