                if (elem[i].name.indexOf('fbzNetcap2') >= 0) continue; //영업용순자본(최근 반기말)				
                if (elem[i].name.indexOf('totRiskAmt1') >= 0) continue; //총위험액(최근 분기말)
                if (elem[i].name.indexOf('totRiskAmt2') >= 0) continue; //총위험액(최근 반기말)				
                if (elem[i].name.indexOf('reqPersisPrincCapVal1') >= 0) continue; //필요유지 자기자본(최근 분기말)
                if (elem[i].name.indexOf('reqPersisPrincCapVal2') >= 0) continue; //필요유지 자기자본(최근 반기말)				
