                    }
                //if(elem[i].name == 'ncrAcntclsYymm1') 				if(!fn_checkDate(elem[i], 'YM')) 		{ elem[i].focus(); return false; }
                //if(elem[i].name == 'ncrAcntclsYymm2') 				if(!fn_checkDate(elem[i], 'YM')) 		{ elem[i].focus(); return false; }
