                    } if (elem[i].name == 'etnListApctContactpnt')
                    if (!scwin.fn_checkPhoneNumber(elem[i])) {
                        elem[i].focus();
                        return false;
                    } if (elem[i].name == 'etnListApctEmail')
                    if (!scwin.fn_checkEmail(elem[i])) {
                        elem[i].focus();
                        return false;
                    }
            } else if (tab == 3) {
                if (elem[i].name.indexOf('creditValuInstTpCd1') >= 0) {
                    if (elem[i].getValue() != '') creditFlag1 = true;
                }
                if (elem[i].name.indexOf('creditGrdContn1') >= 0 || elem[i].name.indexOf('creditGrdChgDd1') >= 0) {
                    if (creditFlag1) {
                        if (elem[i].getValue() == '') {
                            alert('[' + elem[i].id + "] 항목값을 입력해주세요.");
