                            return false;
                        }
                        if (elem[i].name == 'creditGrdContn1')
                            if (!scwin.fn_checkLength(elem[i], 20)) {
                                elem[i].focus();
                                return false;
                            }

                        else if (elem[i].name == 'creditGrdChgDd1')
                            if (!scwin.fn_checkDate(elem[i], 'YMD')) {
                                elem[i].focus();
                                return false;
                            }
                    }
                }
                if (elem[i].name.indexOf('creditValuInstTpCd2') >= 0) {
                    if (elem[i].getValue() != '') creditFlag2 = true;
                }
                if (elem[i].name.indexOf('creditGrdContn2') >= 0 || elem[i].name.indexOf('creditGrdChgDd2') >= 0) {
                    if (creditFlag2) {
                        if (elem[i].getValue() == '') {
                            alert('[' + elem[i].id + "] 항목값을 입력해주세요.");
                            elem[i].focus();
                            return false;
                        }
                        if (elem[i].name == 'creditGrdContn2')
                            if (!scwin.fn_checkLength(elem[i], 20)) {
                                elem[i].focus();
                                return false;
                            }

                        else if (elem[i].name == 'creditGrdChgDd2')
                            if (!scwin.fn_checkDate(elem[i], 'YMD')) {
                                elem[i].focus();
                                return false;
                            }
                    }
                }
                if (elem[i].name.indexOf('creditValuInstTpCd3') >= 0) {
                    if (elem[i].getValue() != '') creditFlag3 = true;
                }
                if (elem[i].name.indexOf('creditGrdContn3') >= 0 || elem[i].name.indexOf('creditGrdChgDd3') >= 0) {
                    if (creditFlag3) {
                        if (elem[i].getValue() == '') {
                            alert('[' + elem[i].id + "] 항목값을 입력해주세요.");
                            elem[i].focus();
                            return false;
                        }
                        if (elem[i].name == 'creditGrdContn3')
                            if (!scwin.fn_checkLength(elem[i], 20)) {
                                elem[i].focus();
                                return false;
                            }

                        else if (elem[i].name == 'creditGrdChgDd3')
                            if (!scwin.fn_checkDate(elem[i], 'YMD')) {
                                elem[i].focus();
                                return false;
                            }
                    }
                }
                if (elem[i].name == 'etnSrtyPrincCapRto1' || elem[i].name == 'etnSrtyPrincCapRto2' || elem[i].name == 'etnSrtyPrincCapRto3') {
                    if (!scwin.fn_checkNumber(elem[i], 'Y')) {
                        elem[i].focus();
                        return false;
                    }
                    if (Number(elem[i].getValue()) > 1000) {
                        alert('[' + elem[i].id + '] 입력값이 너무 큽니다.');
                        elem[i].focus();
                        return false;
                    }
                }
                if (elem[i].name == 'lpNcr1' || elem[i].name == 'lpNcr2' || elem[i].name == 'lpNcr3') {
                    if (!scwin.fn_checkNumber(elem[i], 'Y')) {
                        elem[i].focus();
                        return false;
                    }
                    if (Number(elem[i].getValue()) > 100000) {
                        alert('[' + elem[i].id + '] 입력값이 너무 큽니다.');
                        elem[i].focus();
                        return false;
                    }
                }
            }
        }
    }
    if (tab == 1 && lpCnt == 0) {
        alert('1개 이상의 LP를 입력해야 합니다.');
        document.etnListForm.lp1Cd.focus();
        return false;
    }
    if (tab == 1) {
        if (scwin.chkLpVal(lpValArr)) {
            alert("LP 중복값이 존재합니다.");
            var elmt = "document.etnListForm.lp" + scwin.lpCompare + "Cd";
            eval(elmt).focus();
            return false;
        }
    }
    if (tab == 4) {
        var fileCnt = 0;
        for (var i = 0; i < elem.length; i++) {
            if (elem[i].name.indexOf('etnAttachFile') >= 0 || elem[i].name.indexOf('prevAttachFileNm') >= 0) {
                if (elem[i].getValue() != '') fileCnt++;
            }
        }
        if (fileCnt == 0) {
            alert('1개 이상의 파일을 첨부해야 합니다.');
            return false;
        }
    }
    return true;
};


/**
 * 발행증권에 관한 사항 중 LP중복값을 체크
 * @param pLpArr
 * @returns {Boolean}
 */
/**
 * @method
 * @name chkLpVal
 * @description desc
 * @param {string} pLpArr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkLpVal = function(pLpArr) {
    var lpArr = pLpArr;
    var lpVal = '';
    var lpCompareVal;
    for (var i = 0; i < 5; i++) {
        lpVal = lpArr[i];
        if (lpVal == null) {
            continue;
        }
        for (var j = 0; j < 5; j++) {
            lpCompareVal = lpArr[j];
            if (i == j || lpCompareVal == null) {
                continue;
            }
            if (lpVal == lpCompareVal) {
                scwin.lpCompare = j + 1;
                return true;
            }
        }
    }
    return false;
};
